import java.util.*;

class UndergroundSystemBrute {
    Map<Integer, Object[]> checkIns = new HashMap<>();
    List<Object[]> trips = new ArrayList<>();          // every completed trip stored individually

    void checkIn(int id, String stationName, int t) {
        checkIns.put(id, new Object[]{stationName, t});
    }

    void checkOut(int id, String stationName, int t) {
        Object[] start = checkIns.get(id);
        trips.add(new Object[]{start[0], stationName, t - (int) start[1]});
    }

    double getAverageTime(String startStation, String endStation) {
        double total = 0; int count = 0;
        for (Object[] trip : trips) {                      // scan ALL trips, every query
            if (trip[0].equals(startStation) && trip[1].equals(endStation)) {
                total += (int) trip[2];
                count++;
            }
        }
        return total / count;
    }
}

