    def check_in(self, id, station_name, t):
        self.check_ins[id] = (station_name, t)

    def check_out(self, id, station_name, t):
        start_station, start_time = self.check_ins.pop(id)
        key = (start_station, station_name)
        if key not in self.stats:
            self.stats[key] = [0, 0]
        self.stats[key][0] += t - start_time            # add to running total
        self.stats[key][1] += 1                          # increment running count

    def get_average_time(self, start_station, end_station):
        total, count = self.stats[(start_station, end_station)]
        return total / count                              # O(1) division

