import java.util.*;

class UndergroundSystem {
    Map<Integer, Object[]> checkIns = new HashMap<>();       // id -> (station, time)
    Map<String, double[]> stats = new HashMap<>();            // route key -> [totalTime, count]

    void checkIn(int id, String stationName, int t) {
        checkIns.put(id, new Object[]{stationName, t});
    }

    void checkOut(int id, String stationName, int t) {
        Object[] start = checkIns.remove(id);
        String key = start[0] + "->" + stationName;
        stats.putIfAbsent(key, new double[]{0, 0});
        double[] s = stats.get(key);
        s[0] += t - (int) start[1];                            // add to running total
        s[1] += 1;                                              // increment running count
    }

    double getAverageTime(String startStation, String endStation) {
        double[] s = stats.get(startStation + "->" + endStation);
        return s[0] / s[1];                                      // O(1) division
    }
}

