#include <bits/stdc++.h>
using namespace std;

class UndergroundSystem {
public:
    unordered_map<int, pair<string,int>> checkIns;             // id -> (station, time)
    map<pair<string,string>, pair<double,int>> stats;            // route -> (totalTime, count)

    void checkIn(int id, string stationName, int t) {
        checkIns[id] = {stationName, t};
    }

    void checkOut(int id, string stationName, int t) {
        auto [s, startTime] = checkIns[id];
        checkIns.erase(id);
        auto& stat = stats[{s, stationName}];
        stat.first += t - startTime;                              // add to running total
        stat.second += 1;                                          // increment running count
    }

    double getAverageTime(string startStation, string endStation) {
        auto& stat = stats[{startStation, endStation}];
        return stat.first / stat.second;                            // O(1) division
    }
};
